import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        long val;
        Node left, right;
        Node(long v) { this.val = v; }
    }
    static Node buildTree(String[] tokens) {
        if (tokens.length == 0 || tokens[0].equals("null")) return null;
        Node root = new Node(Long.parseLong(tokens[0]));
        Queue<Node> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.length) {
            Node curr = q.poll();
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.left = new Node(Long.parseLong(tokens[i]));
                q.add(curr.left);
            }
            i++;
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.right = new Node(Long.parseLong(tokens[i]));
                q.add(curr.right);
            }
            i++;
        }
        return root;
    }
    static boolean searchBst(Node root, long target) {
        Node curr = root;
        while (curr != null) {
            if (curr.val == target) return true;
            else if (target < curr.val) curr = curr.left;
            else curr = curr.right;
        }
        return false;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line1 = br.readLine();
        if (line1 == null || line1.trim().isEmpty()) { System.out.println("false"); return; }
        long target = Long.parseLong(line1.trim());
        String line2 = br.readLine();
        if (line2 == null || line2.trim().isEmpty()) { System.out.println("false"); return; }
        String[] tokens = line2.trim().split("\\s+");
        Node root = buildTree(tokens);
        System.out.println(searchBst(root, target) ? "true" : "false");
    }
}

