import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        String val;
        Node left, right, next;
        Node(String v) { this.val = v; }
    }
    static Node buildTree(String[] tokens) {
        if (tokens.length == 0 || tokens[0].equals("null")) return null;
        Node root = new Node(tokens[0]);
        Queue<Node> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.length) {
            Node curr = q.poll();
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.left = new Node(tokens[i]);
                q.add(curr.left);
            }
            i++;
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.right = new Node(tokens[i]);
                q.add(curr.right);
            }
            i++;
        }
        return root;
    }
    static void inorder(Node node, List<Node> nodes) {
        if (node == null) return;
        inorder(node.left, nodes);
        nodes.add(node);
        inorder(node.right, nodes);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) { System.out.println(); return; }
        String[] tokens = line.trim().split("\\s+");
        Node root = buildTree(tokens);
        if (root == null) { System.out.println(); return; }
        List<Node> nodes = new ArrayList<>();
        inorder(root, nodes);
        for (int i = 0; i < nodes.size() - 1; i++) nodes.get(i).next = nodes.get(i + 1);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < nodes.size(); i++) {
            if (i > 0) sb.append(' ');
            Node n = nodes.get(i);
            sb.append(n.val).append("->").append(n.next != null ? n.next.val : "null");
        }
        System.out.println(sb);
    }
}

