    Node *left = nullptr, *right = nullptr, *next = nullptr;
    Node(string v) : val(v) {}
};

Node* buildTree(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;
    Node* root = new Node(tokens[0]);
    queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {
        Node* curr = q.front(); q.pop();
        if (i < tokens.size() && tokens[i] != "null") {
            curr->left = new Node(tokens[i]);
            q.push(curr->left);
        }
        i++;
        if (i < tokens.size() && tokens[i] != "null") {
            curr->right = new Node(tokens[i]);
            q.push(curr->right);
        }
        i++;
    }
    return root;
}

void inorder(Node* node, vector<Node*>& nodes) {
    if (!node) return;
