import sys
from collections import deque

class Node:
    def __init__(self, val):
        self.val = int(val)
        self.left = None
        self.right = None

def build_tree(tokens):
    if not tokens or tokens[0] == 'null': return None
    root = Node(tokens[0])
    q = deque([root])
    i = 1
    while q and i < len(tokens):
        curr = q.popleft()
        if i < len(tokens) and tokens[i] != 'null':
            curr.left = Node(tokens[i])
            q.append(curr.left)
        i += 1
        if i < len(tokens) and tokens[i] != 'null':
            curr.right = Node(tokens[i])
            q.append(curr.right)
        i += 1
    return root

def lca_bst(root, u, v):
    curr = root
    while curr:
        if u < curr.val and v < curr.val:
            curr = curr.left
        elif u > curr.val and v > curr.val:
            curr = curr.right
        else:
            return curr.val
    return -1

