import sys
from collections import deque

class Node:
    def __init__(self, val):
        self.val = int(val)
        self.left = None
        self.right = None

def build_tree(tokens):
    if not tokens or tokens[0] == 'null': return None
    root = Node(tokens[0])
    q = deque([root])
    i = 1
    while q and i < len(tokens):
        curr = q.popleft()
        if i < len(tokens) and tokens[i] != 'null':
            curr.left = Node(tokens[i])
            q.append(curr.left)
        i += 1
        if i < len(tokens) and tokens[i] != 'null':
            curr.right = Node(tokens[i])
            q.append(curr.right)
        i += 1
    return root

def count_range(node, low, high):
    if not node: return 0
    if node.val < low: return count_range(node.right, low, high)
    if node.val > high: return count_range(node.left, low, high)
    return 1 + count_range(node.left, low, high) + count_range(node.right, low, high)

def solve():
    lines = [line.strip() for line in sys.stdin.read().split('\n') if line.strip()]
    if not lines: print(0); return
    low, high = [int(x) for x in lines[0].split()]
    tokens = lines[1].split() if len(lines) > 1 else []
    root = build_tree(tokens)
    print(count_range(root, low, high))

if __name__ == '__main__':
    solve()

