import sys

class IntervalNode:
    def __init__(self, low, high):
        self.low = low
        self.high = high
        self.max = high
        self.left = None
        self.right = None

def insert_interval(root, low, high):
    if not root: return IntervalNode(low, high)
    if low < root.low:
        root.left = insert_interval(root.left, low, high)
    else:
        root.right = insert_interval(root.right, low, high)
    root.max = max(root.max, high)
    return root

def check_overlap(root, low, high):
    if not root: return False
    if max(root.low, low) < min(root.high, high): return True
    if root.left and root.left.max > low:
        return check_overlap(root.left, low, high)
    return check_overlap(root.right, low, high)

def solve():
    tokens = sys.stdin.read().split()
    if not tokens: return
    n = int(tokens[0])
    root = None
    rejected = []
    idx = 1
    for i in range(n):
        s = int(tokens[idx]); idx += 1
        e = int(tokens[idx]); idx += 1
        if check_overlap(root, s, e):
            rejected.append(i)
        else:
            root = insert_interval(root, s, e)
    if not rejected: print('NONE')
    else: print(' '.join(map(str, rejected)))

if __name__ == '__main__':
    solve()

