import java.util.*;

public class Main {
    static class Node {
        long low, high, max;
        Node left, right;
        Node(long l, long h) { this.low = l; this.high = h; this.max = h; }
    }
    static Node insert(Node root, long low, long high) {
        if (root == null) return new Node(low, high);
        if (low < root.low) root.left = insert(root.left, low, high);
        else root.right = insert(root.right, low, high);
        root.max = Math.max(root.max, high);
        return root;
    }
    static boolean checkOverlap(Node root, long low, long high) {
        if (root == null) return false;
        if (Math.max(root.low, low) < Math.min(root.high, high)) return true;
        if (root.left != null && root.left.max > low) return checkOverlap(root.left, low, high);
        return checkOverlap(root.right, low, high);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        int n = Integer.parseInt(line.trim());
        Node root = null;
        List<Integer> rejected = new ArrayList<>();
        StringTokenizer st = null;
        for (int i = 0; i < n; i++) {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            long s = Long.parseLong(st.nextToken());
            long e = Long.parseLong(st.nextToken());
            if (checkOverlap(root, s, e)) {
                rejected.add(i);
            } else {
                root = insert(root, s, e);
            }
        }
        if (rejected.isEmpty()) System.out.println("NONE");
        else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rejected.size(); i++) {
                if (i > 0) sb.append(' ');
                sb.append(rejected.get(i));
            }
            System.out.println(sb);
        }
    }
}

