#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Node {
    long long low, high, maxVal;
    Node *left = nullptr, *right = nullptr;
    Node(long long l, long long h) : low(l), high(h), maxVal(h) {}
};

Node* insertNode(Node* root, long long low, long long high) {
    if (!root) return new Node(low, high);
    if (low < root->low) root->left = insertNode(root->left, low, high);
    else root->right = insertNode(root->right, low, high);
    root->maxVal = max(root->maxVal, high);
    return root;
}

bool checkOverlap(Node* root, long long low, long long high) {
    if (!root) return false;
    if (max(root->low, low) < min(root->high, high)) return true;
    if (root->left && root->left->maxVal > low) return checkOverlap(root->left, low, high);
    return checkOverlap(root->right, low, high);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    Node* root = nullptr;
    vector<int> rejected;
    for (int i = 0; i < n; i++) {
        long long s, e;
        cin >> s >> e;
        if (checkOverlap(root, s, e)) {
            rejected.push_back(i);
        } else {
            root = insertNode(root, s, e);
        }
    }
    if (rejected.empty()) cout << "NONE\n";
    else {
        for (size_t i = 0; i < rejected.size(); i++) {
            if (i > 0) cout << ' ';
            cout << rejected[i];
        }
        cout << "\n";
    }
    return 0;
}

