import sys
from collections import deque

class Node:
    def __init__(self, val):
        self.val = int(val)
        self.left = None
        self.right = None

def build_tree(tokens):
    if not tokens or tokens[0] == 'null': return None
    root = Node(tokens[0])
    q = deque([root])
    i = 1
    while q and i < len(tokens):
        curr = q.popleft()
        if i < len(tokens) and tokens[i] != 'null':
            curr.left = Node(tokens[i])
            q.append(curr.left)
        i += 1
        if i < len(tokens) and tokens[i] != 'null':
            curr.right = Node(tokens[i])
            q.append(curr.right)
        i += 1
    return root

def has_dead_end(node, min_val, max_val):
    if not node: return False
    if not node.left and not node.right:
        if min_val == max_val: return True
    return has_dead_end(node.left, min_val, node.val - 1) or has_dead_end(node.right, node.val + 1, max_val)

def solve():
    tokens = sys.stdin.read().split()
    root = build_tree(tokens)
    if not root: print('false'); return
    print('true' if has_dead_end(root, 1, float('inf')) else 'false')

if __name__ == '__main__':
    solve()

