import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        long val;
        Node left, right;
        Node(long v) { this.val = v; }
    }
    static Node buildTree(String[] tokens) {
        if (tokens.length == 0 || tokens[0].equals("null")) return null;
        Node root = new Node(Long.parseLong(tokens[0]));
        Queue<Node> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.length) {
            Node curr = q.poll();
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.left = new Node(Long.parseLong(tokens[i]));
                q.add(curr.left);
            }
            i++;
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.right = new Node(Long.parseLong(tokens[i]));
                q.add(curr.right);
            }
            i++;
        }
        return root;
    }
    static boolean hasDeadEnd(Node node, long minVal, long maxVal) {
        if (node == null) return false;
        if (node.left == null && node.right == null) {
            if (minVal == maxVal) return true;
        }
        return hasDeadEnd(node.left, minVal, node.val - 1) || hasDeadEnd(node.right, node.val + 1, maxVal);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) { System.out.println("false"); return; }
        String[] tokens = line.trim().split("\\s+");
        Node root = buildTree(tokens);
        System.out.println(hasDeadEnd(root, 1, Long.MAX_VALUE) ? "true" : "false");
    }
}

