        if (i < tokens.size() && tokens[i] != "null") {
            curr->left = new Node(stoll(tokens[i]));
            q.push(curr->left);
        }
        i++;
        if (i < tokens.size() && tokens[i] != "null") {
            curr->right = new Node(stoll(tokens[i]));
            q.push(curr->right);
        }
        i++;
    }
    return root;
}

