            i++;
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.right = new Node(Long.parseLong(tokens[i]));
                q.add(curr.right);
            }
            i++;
        }
        return root;
    }
    static int maxSize = 0;
    static class Info {
        boolean isBst;
        int size;
        long minVal, maxVal;
        Info(boolean b, int s, long mn, long mx) {
            this.isBst = b; this.size = s; this.minVal = mn; this.maxVal = mx;
        }
    }
    static Info postorder(Node node) {
        if (node == null) return new Info(true, 0, Long.MAX_VALUE, Long.MIN_VALUE);
        Info l = postorder(node.left);
        Info r = postorder(node.right);
        if (l.isBst && r.isBst && l.maxVal < node.val && node.val < r.minVal) {
            int sz = 1 + l.size + r.size;
            maxSize = Math.max(maxSize, sz);
            return new Info(true, sz, Math.min(l.minVal, node.val), Math.max(r.maxVal, node.val));
        }
        return new Info(false, Math.max(l.size, r.size), 0, 0);
    }
    public static void main(String[] args) throws IOException {
