    vector<Node*> nodes;
    inorder(root, nodes);
    for (size_t i = 0; i < nodes.size(); i++) {
        nodes[i]->left = nullptr;
        nodes[i]->right = (i + 1 < nodes.size()) ? nodes[i + 1] : nullptr;
    }
    Node* curr = nodes[0];
    bool first = true;
    while (curr) {
        if (!first) cout << ' ';
        cout << curr->val;
        first = false;
        curr = curr->right;
    }
